// Signs an outgoing request to Convex: HMAC-SHA256 over `${ts}.${METHOD} ${path}.${body}`.
const crypto = require('crypto');
const secret = $env.LENDLOOP_N8N_SECRET;
if (!secret || secret.length < 32) throw new Error('LENDLOOP_N8N_SECRET is not set (min 32 chars)');
function signed(method, path, body) {
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = crypto.createHmac('sha256', secret).update(`${ts}.${method} ${path}.${body}`).digest('hex');
  return { ts, sig };
}

const e = $input.first().json;
const body = JSON.stringify({ executionId: String(e.execution?.id ?? Date.now()), workflow: e.workflow?.name ?? 'unknown',
  node: e.execution?.lastNodeExecuted ?? 'unknown', message: String(e.execution?.error?.message ?? 'unknown error').slice(0, 200) });
console.error(`[LendLoop error] ${body}`);
return [{ json: { ...signed('POST', '/n8n/workflow-error', body), body } }];
